def apply_aggregation(result_grid, agg_fn_name, relation_type="diag"):
    """Fill empty sections using aggregation"""
    # First copy all existing special values
    for r in range(15):
        for c in range(19):
            if r not in divider_rows and c not in divider_cols:
                sec_r = next(i for i, rr in enumerate(row_ranges) if rr[0] <= r <= rr[1])
                sec_c = next(i for i, cc in enumerate(col_ranges) if cc[0] <= c <= cc[1])

                current_val = grid[r][c]

                if current_val != 4:
                    result_grid[r][c] = current_val

    def get_vals_at_pos(sec_sr, sec_sc):
        vals = []
        for sr in range(4):
            for sc in range(4):
                lr_fn, lc_fn = None, None
                if relation_type == "diag":
                    sr_use = (sr+2)%4
                    sc_use = (sc+2)%4
                elif relation_type == "opp_row":
                    sr_use = (sr+2)%4
                    sc_use = sc
                else:
                    sr_use, sc_use = sr, sc

                try:
                    val = sections_data[(sr_use, sc_use)]['region'][local_r][local_c]
                    if val != 4:
                        vals.append(val)
                except IndexError:
                    pass
        return vals

    for r in range(15):
        for c in range(19):
            if r in divider_rows or c in divider_cols:
                continue

            sec_r = next(i for i, rr in enumerate(row_ranges) if rr[0] <= r <= rr[1])
            sec_c = next(i for i, cc in enumerate(col_ranges) if cc[0] <= c <= cc[1])

            local_r = r - row_ranges[sec_r][0]
            local_c = c - col_ranges[sec_c][0]

            if grid[r][c] != 4:
                continue

            vals = get_vals_at_pos(sec_r, sec_c)

            if vals:
                if agg_fn_name == "most_common":
                    best_counts = Counter(vals)
                    agg = best_counts.most_common(1)[0][0] if best_counts else 4
                elif agg_fn_name == "max":
                    agg = max(vals)
                elif agg_fn_name == "sorted_unique_max":
                    sorted_uniq = sorted(set(vals))
                    agg = sorted_uniq[-1]
                else:
                    agg = vals[0]

                result_grid[r][c] = agg

